const REC_SCHEMA = {
  type: 'object',
  properties: {
    issue: { type: 'integer' },
    applied: { type: 'array', items: { type: 'string' } },
    skipped: { type: 'array', items: { type: 'string' } },
    note: { type: 'string' },
  },
  required: ['issue', 'applied', 'skipped', 'note'],
  additionalProperties: false,
}

phase('Reconcile')
const results = await parallel(Object.keys(TARGETS).map(t => () => agent(
`You are reconciling GitHub issue #${t} in anadon/jls. Per-issue fixer agents recently rewrote all 605 open issues but were forbidden from editing issues other than their own; they reported that #${t} needs the following changes:

${JSON.stringify(TARGETS[t], null, 2)}

Load tools via ToolSearch query "select:mcp__github__issue_read,mcp__github__issue_write". Fetch #${t}'s CURRENT body first (it was itself rewritten recently — never work from assumptions). For each requested change, verify it against the current state of both endpoints (fetch the counterpart issue when the change concerns a blocked_by/blocks mirror or a claim about another issue's content; repo convention: every dependency edge must be declared on both endpoints). Apply the changes that verify with a surgical issue_write "update" — edit only the sections/lines involved and preserve the rest of the body exactly. If requests conflict, resolve from the counterpart issues' actual current declarations and explain. Skip anything already satisfied, wrong, or explicitly requiring a human decision per its own reason text (return those in skipped with the reason). Do not post comments; do not edit any issue other than #${t}; retry rate-limited writes up to 4 times.

Return via StructuredOutput: issue=${t}; applied=[each change applied, one string]; skipped=[each skip with its reason]; note.`,
  { label: `edge:${t}`, phase: 'Reconcile', model: 'sonnet', schema: REC_SCHEMA }
)))
const done = results.filter(Boolean)
log(`Reconcile chunk 1: ${done.length}/${Object.keys(TARGETS).length} targets processed`)
return { chunk: 1, done: done.length, expected: Object.keys(TARGETS).length, results: done }
